const secoes = [
  { secao: "Introdução – Manual de Políticas Internas e Procedimentos (TechNova Soluções Ltda., versão 1.2, 10 de janeiro de 2024, RH / Operações)", texto: "Este documento descreve as políticas e os procedimentos operacionais padrão que todos os colaboradores da TechNova Soluções Ltda. devem seguir. O não cumprimento destas regras pode resultar em medidas disciplinares." },
  { secao: "Seção 1.1 – Política de Senhas Corporativas (página 1)", texto: "Para garantir a segurança dos sistemas centrais, todos os colaboradores devem seguir os seguintes requisitos de senha. Comprimento mínimo: 12 caracteres. Complexidade: deve conter pelo menos uma letra maiúscula, uma letra minúscula, um número e um caractere especial (ex: @, #, $). Rotação obrigatória: as senhas devem ser alteradas a cada 60 dias. Histórico: não é permitido reutilizar as últimas 5 senhas." },
  { secao: "Seção 1.2 – Uso de Dispositivos Pessoais (BYOD) (página 1)", texto: "Colaboradores estão autorizados a usar dispositivos pessoais (celulares e tablets) para acessar e-mails corporativos e ferramentas de chat (ex: Slack), desde que: o dispositivo possua um bloqueio de tela (senha ou biometria); e o colaborador instale o software de gerenciamento de dispositivos móveis (MDM) da TechNova. Proibição: é estritamente proibido armazenar arquivos de clientes ou código-fonte da empresa em armazenamento local de dispositivos pessoais não homologados pela TI." },
  { secao: "Seção 2.1 – Trabalho Remoto: Elegibilidade e Escala (página 1)", texto: "A TechNova adota um modelo híbrido flexível para a maioria das funções. Modelo padrão: os colaboradores devem comparecer ao escritório físico (Sede São Paulo) pelo menos 2 dias por semana. Escala: a escala de dias presenciais deve ser acordada diretamente com o gestor direto e registrada no sistema ERP até a última sexta-feira do mês anterior. Exceções: funções de Infraestrutura de Rede e Suporte Presencial não são elegíveis para trabalho remoto regular, exigindo presença de 5 dias na semana." },
  { secao: "Seção 2.2 – Reembolso de Despesas de Home Office (página 2)", texto: "A empresa oferece um auxílio mensal fixo de R$ 150,00 para cobrir despesas de internet e energia elétrica para colaboradores em modelo híbrido. Este valor é pago diretamente na folha de pagamento. Despesas com mobiliário (cadeiras, mesas) exigem aprovação prévia do Departamento de Operações e são limitadas a R$ 500,00 a cada 2 anos." },
  { secao: "Seção 3.1 – Política de Férias (página 2)", texto: "Avisos prévios: solicitações de férias de 10 dias ou mais devem ser submetidas no portal do RH com pelo menos 45 dias de antecedência. Solicitações de períodos menores (menos de 10 dias) exigem 15 dias de antecedência. Aprovação: todas as férias dependem da aprovação do gestor, considerando a carga de trabalho da equipe." },
  { secao: "Seção 3.2 – Dia de Folga de Aniversário (Birthday Off) (página 2)", texto: "A TechNova concede um dia de folga remunerada no mês do aniversário do colaborador. Regra de uso: a folga deve ser gozada obrigatoriamente dentro do mês calendário do aniversário e não pode ser acumulada para o ano seguinte. Notificação: o colaborador deve notificar o gestor e o RH com 7 dias de antecedência." },
  { secao: "Seção 4.1 – Relato de Incidentes de Segurança de Dados (página 2)", texto: "Qualquer suspeita de vazamento de dados, perda de equipamento corporativo (notebook) ou ataque de phishing bem-sucedido deve ser reportada imediatamente (em até 1 hora após a detecção) para o e-mail: security-alert@technova.com.br e para o ramal interno 4040." }
];
return secoes.map(s => ({ json: s }));
